class_name StoryPlayer
extends Node

signal story_finished

@export var story_file_path: String = "res://story/intro.json"
@export var dialogue_box: PanelContainer
@export var character_stage: CharacterStage

var _lines: Array = []
var _current_line_index: int = 0


func _ready() -> void:
	if dialogue_box:
		dialogue_box.line_finished.connect(_on_dialogue_box_line_finished)

	if load_story(story_file_path):
		start_story()


func load_story(path: String) -> bool:
	if not FileAccess.file_exists(path):
		print("Errore: file della storia non trovato: ", path)
		return false

	var file := FileAccess.open(path, FileAccess.READ)
	if not file:
		print("Errore durante l'apertura del file: ", path)
		return false

	var json := JSON.new()
	var parse_result := json.parse(file.get_as_text())
	if parse_result != OK:
		print("Errore nel parsing del JSON: ", json.get_error_message())
		return false

	var data: Dictionary = json.data
	if not data.has("lines"):
		print("Errore: la chiave 'lines' non è presente nel file JSON.")
		return false

	_lines = data["lines"]
	_current_line_index = 0
	return true


func start_story() -> void:
	if _lines.is_empty():
		return
	_current_line_index = 0
	_show_current_line()


func advance() -> void:
	_current_line_index += 1
	if _current_line_index < _lines.size():
		_show_current_line()
	else:
		if dialogue_box:
			dialogue_box.clear()
		story_finished.emit()


func get_line_count() -> int:
	return _lines.size()


func restart_story() -> void:
	if _lines.is_empty():
		return
	_current_line_index = 0
	_show_current_line()


func jump_to_line(index: int) -> bool:
	if index < 0 or index >= get_line_count():
		return false
	_current_line_index = index
	_show_current_line()
	return true


func is_at_end() -> bool:
	return _current_line_index >= get_line_count()


func get_character_stage() -> CharacterStage:
	return character_stage


func _show_current_line() -> void:
	if _current_line_index < 0 or _current_line_index >= _lines.size():
		return

	var line_data: Dictionary = _lines[_current_line_index]
	var speaker: String = line_data.get("speaker", "")
	var text: String = line_data.get("text", "")

	if dialogue_box:
		dialogue_box.show_line(speaker, text)

	if character_stage and not speaker.is_empty():
		character_stage.focus_character(speaker.to_lower())


func _on_dialogue_box_line_finished() -> void:
	advance()
```

## Parte teorica della lezione (sintesi)
# Sfondi e transizioni: dissolvenze e chiusure a nero
In questa lezione impari a organizzare la scena visiva di una visual novel nei suoi strati fondamentali (sfondo, figure dei personaggi e interfaccia). Scoprirai come realizzare dissolvenze incrociate tra due immagini usando due TextureRect sovrapposti e come gestire chiusure e aperture a nero con un ColorRect. Infine vedrai come usare await con i segnali dei Tween per sincronizzare l'avanzamento della narrazione con i tempi delle animazioni visive.

In una visual novel il cambio di ambientazione scandisce il tempo e il ritmo narrativo. Nel nostro gioco «Storie», Elena comincia parlando nel buio completo, per poi ricordare la biblioteca e infine trovarsi nell'Archivio. Se cambiassimo l'immagine di sfondo di scatto, l'effetto sarebbe brusco e spezzerebbe l'illusione narrativa. Per creare un'esperienza immersiva servono transizioni graduali: una dissolvenza incrociata (*crossfade*), in cui un'immagine sfuma lentamente nell'altra, e la chiusura a nero (*fade to black*), che stacca un momento narrativo dal successivo. Inoltre, il motore deve poter attendere la fine dell'animazione prima di mostrare le battute successive.

In Godot 2D e nell'interfaccia, gli elementi vengono disegnati sullo schermo seguendo il loro *ordine nell'albero* (*tree order*): i nodi posti più in alto nell'elenco del pannello *Scene* (albero dei nodi) vengono disegnati per primi (dietro), mentre i nodi posti più in basso vengono disegnati sopra a quelli precedenti. In una visual novel questo stabilisce una gerarchia visiva ben precisa divisa in quattro livelli:

1. **Sfondo**: l'ambiente illustrato, posizionato alla base di tutto.
2. **Figure dei personaggi**: i nodi `CharacterDisplay` che mostrano chi parla o chi è presente nella stanza.
3. **Velo di oscuramento**: un rettangolo nero a schermo intero (`ColorRect`) utilizzato per nascondere o rivelare l'ambiente.
4. **Interfaccia utente (UI)**: la nostra `DialogueBox` con il testo e i controlli, posizionata in primo piano per restare sempre visibile e leggibile anche durante i cambi di scenario.

Creare la scena BackgroundDisplay
1. Nel pannello *Scene* premi **+** (o premi Ctrl+A) e crea un nodo radice di tipo **Control**. Chiamalo `BackgroundDisplay`.
2. Con il nodo `BackgroundDisplay` selezionato, nell'area di lavoro 2D usa il menu delle ancore in alto per impostarlo su **Full Rect** (ancore su tutti e quattro i lati a 0 e 1), in modo che occupi l'intera finestra.
3. Seleziona `BackgroundDisplay`, premi **+** e aggiungi un nodo **TextureRect**. Rinominalo in `CurrentBackground`. Nel pannello *Inspector* (ispettore) imposta le ancore su **Full Rect**, `expand_mode` su `Ignore Size` (valore 1) e `stretch_mode` su `Keep Aspect Covered` (valore 6) affinché l'immagine copra lo schermo senza deformarsi.
4. Aggiungi un secondo **TextureRect** come figlio di `BackgroundDisplay` e nominalo `CrossfadeBackground`. Assegna le stesse impostazioni di ancore e ridimensionamento di `CurrentBackground`.
5. Aggiungi come terzo figlio di `BackgroundDisplay` un nodo **ColorRect** e rinominalo in `BlackOverlay`. Imposta le ancore su **Full Rect** e il parametro `color` su nero puro (`Color(0, 0, 0, 1)`).
6. Salva la nuova scena premendo Ctrl+S nel percorso `res://story/background_display.tscn`.

Per realizzare una dissolvenza tra due immagini servono due nodi `TextureRect` distinti: se ne usassimo uno solo e cambiassimo la sua proprietà `texture`, Godot sostituirebbe l'immagine in un singolo fotogramma. Se provassimo ad abbassare l'alfa dell'unico nodo, vedremmo lo sfondo vuoto del motore invece della nuova stanza.

Con due immagini sovrapposte il procedimento diventa pulito: `CurrentBackground` mostra lo sfondo di partenza; quando ordiniamo un cambio, assegniamo la nuova immagine a `CrossfadeBackground`, impostiamo la sua trasparenza (`modulate:a`) a zero e usiamo un `Tween` per portarla a 1.0. A quel punto l'immagine superiore copre interamente quella inferiore: possiamo quindi copiare la nuova texture su `CurrentBackground` e reimpostare `CrossfadeBackground` trasparente e vuoto, pronti per la transizione successiva.

La transizione attraverso il nero funziona secondo un principio simile ma sfrutta il rettangolo nero `BlackOverlay`. Invece di mescolare due disegni, aumentiamo `modulate:a` di `BlackOverlay` da 0.0 a 1.0 per far calare il buio. Quando lo schermo è completamente nero, cambiamo istantaneamente la texture di `CurrentBackground` senza che il giocatore se ne accorga, e poi riduciamo `modulate:a` del velo nero da 1.0 a 0.0 per riaprire la scena sul nuovo luogo.

In Godot le animazioni create con i `Tween` operano in parallelo fotogramma per fotogramma senza bloccare il resto del programma. Se richiamassimo una funzione di transizione e subito dopo mostrassimo una riga di testo, il dialogo apparirebbe all'istante mentre lo schermo è ancora nel bel mezzo della dissolvenza.

Per sincronizzare la narrazione con la grafica usiamo `await`: ogni `Tween` espone il segnale `finished`, emesso nell'istante esatto in cui l'interpolazione si conclude. Scrivendo `await _fade_tween.finished`, sospendiamo l'esecuzione della funzione fino al termine dell'animazione, garantendo che il codice chiamante non prosegua prima del tempo.

```gdscript
class_name BackgroundDisplay
extends Control

var _fade_tween: Tween
var _crossfade_tween: Tween

@onready var current_background: TextureRect = $CurrentBackground
@onready var crossfade_background: TextureRect = $CrossfadeBackground
@onready var black_overlay: ColorRect = $BlackOverlay


func _ready() -> void:
	crossfade_background.modulate.a = 0.0
	black_overlay.modulate.a = 0.0


func set_background(texture: Texture2D) -> void:
	if _crossfade_tween and _crossfade_tween.is_running():
		_crossfade_tween.kill()
	current_background.texture = texture
	crossfade_background.texture = null
	crossfade_background.modulate.a = 0.0


func crossfade_to(new_texture: Texture2D, duration: float = 0.5) -> void:
	if duration <= 0.0:
		set_background(new_texture)
		return

	if _crossfade_tween and _crossfade_tween.is_running():
		_crossfade_tween.kill()

	crossfade_background.texture = new_texture
	crossfade_background.modulate.a = 0.0

	_crossfade_tween = create_tween()
	_crossfade_tween.tween_property(crossfade_background, "modulate:a", 1.0, duration)
	await _crossfade_tween.finished

	current_background.texture = new_texture
	crossfade_background.texture = null
	crossfade_background.modulate.a = 0.0


func fade_to_black(duration: float = 0.5) -> void:
	if duration <= 0.0:
		black_overlay.modulate.a = 1.0
		return

	if _fade_tween and _fade_tween.is_running():
		_fade_tween.kill()

	_fade_tween = create_tween()
	_fade_tween.tween_property(black_overlay, "modulate:a", 1.0, duration)
	await _fade_tween.finished


func fade_from_black(duration: float = 0.5) -> void:
	if duration <= 0.0:
